using UnityEngine;

namespace Astrea;

public class CorruptedAnimalInitializer : MonoBehaviour
{
	[Header("Components To Initialize")]
	[SerializeField]
	private CorruptedAnimalCorruptionStats corruptedAnimalCorruptionStats;

	[SerializeField]
	private CorruptedAnimalActivation corruptedAnimalActivation;

	[SerializeField]
	private CorruptedAnimalSpriteControl corruptedAnimalSpriteControl;

	[SerializeField]
	private CorruptedAnimalEffects corruptedAnimalEffects;

	[SerializeField]
	private CorruptedAnimalOverCorruption corruptedAnimalOverCorruption;

	[SerializeField]
	private UnitDialogue unitDialogue;

	[SerializeField]
	private TooltipNameInstance tooltipNameInstance;

	[Header("Difficulty Levels")]
	[SerializeField]
	private DifficultyLevels difficultyLevels;

	private CorruptedAnimalData corruptedAnimalData;

	public CorruptedAnimalOverCorruption CorruptedAnimalOverCorruption => corruptedAnimalOverCorruption;

	public CorruptedAnimalData CorruptedAnimalData => corruptedAnimalData;

	public void Initialize(CorruptedAnimalData corruptedAnimalData, bool startBattleInitialize, bool dontInitializeSpriteControl = false)
	{
		this.corruptedAnimalData = corruptedAnimalData;
		corruptedAnimalCorruptionStats.Initialize(corruptedAnimalData, startBattleInitialize);
		if (!dontInitializeSpriteControl)
		{
			corruptedAnimalSpriteControl.Initialize(corruptedAnimalData, corruptedAnimalCorruptionStats, startBattleInitialize);
		}
		corruptedAnimalEffects.Initialize(corruptedAnimalData, startBattleInitialize);
		corruptedAnimalOverCorruption.Initialize(corruptedAnimalData);
		Dice dice = null;
		int currentDifficultyLevelModifyEnemiesHighestIndex = difficultyLevels.GetCurrentDifficultyLevelModifyEnemiesHighestIndex();
		dice = ((corruptedAnimalData.DiceList.Count <= currentDifficultyLevelModifyEnemiesHighestIndex) ? corruptedAnimalData.DiceList.Last() : corruptedAnimalData.DiceList[currentDifficultyLevelModifyEnemiesHighestIndex]);
		corruptedAnimalActivation.Initialize(dice);
		corruptedAnimalActivation.InitializeCorruptedAnimalData(corruptedAnimalData);
		if (corruptedAnimalData.EnableUnitsMiscData && corruptedAnimalData.UnitsMiscData.EnableDialogueData)
		{
			unitDialogue.Initialize(corruptedAnimalData.UnitsMiscData.DialogueData);
			unitDialogue.HasDialogueTypeShowDialogueBoxRandomDialogue(DialogueTypeEnum.STARTOFBATTLE);
		}
		InitializeTooltipNameInstance(corruptedAnimalData);
	}

	public void InitializeTooltipNameInstance(CorruptedAnimalData corruptedAnimalData)
	{
		tooltipNameInstance.Initialize(corruptedAnimalData.GetLocalizedName());
	}

	public void CorruptedAnimalSpriteControlInitialize(CorruptedAnimalData corruptedAnimalData)
	{
		corruptedAnimalSpriteControl.Initialize(corruptedAnimalData, corruptedAnimalCorruptionStats, startBattleInitialize: false);
	}

	public bool EnemyHasStartOfBattleSFXPlayIt()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if ((bool)enemySFXData && enemySFXData.EnableStartOfBattle)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemySFXData.StartOfBattle);
			return true;
		}
		return false;
	}

	public bool EnemyHasStartOfBattleSFX()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if ((bool)enemySFXData && enemySFXData.EnableStartOfBattle)
		{
			return true;
		}
		return false;
	}

	public void InitializeForDebug(CorruptedAnimalData corruptedAnimalData)
	{
		corruptedAnimalCorruptionStats.Initialize(corruptedAnimalData, startBattleInitialize: true);
		corruptedAnimalSpriteControl.Initialize(corruptedAnimalData, corruptedAnimalCorruptionStats, startBattleInitialize: true);
		corruptedAnimalOverCorruption.Initialize(corruptedAnimalData);
	}
}
